import pandas as pd
p='xe_kr_mof_bo_artifacts/20260812_154010/bo_improvement_curve.csv'
df=pd.read_csv(p)
last=-1
for _,r in df.iterrows():
 if r.scalarized_desirability > last+1e-12:
  print(int(r.eval), r.candidate, f"score={r.scalarized_desirability:.6f}", f"sel={r.selectivity_proxy:.4f}", f"cap={r.capacity_proxy_cm3_g:.4f}")
  last=r.scalarized_desirability
PY","timeout_seconds":30}

